insert into public.actor_cards (id, actor_name, scene_title, thread, status, session_date, actor_brief, actor_direction, questions, optional_action, director_goal, director_notes, shot_ids) values ('AC-001', 'Glen', 'The Legend of Jim — Who is Jim?', 'The Legend of Jim', 'Idea', NULL, 'You are helping Bryan build the set, but people keep referring to Jim S, the former set builder. You have not met him.', 'Keep doing your actual work. Respond naturally when Jim is mentioned; you do not need to act confused if you are not.', 'How many times have you heard Jim mentioned?
Have you actually met Jim S?
What do people expect Jim to know?
Who is doing the construction now?', 'During a natural pause, you might ask: Who is Jim?', 'Establish the repeated Jim S references without making Glen seem incompetent.', 'Possible later payoff: Jim S says, “Have you asked Bryan?” Do not share this punchline as an actor instruction.', 'B01, B02, B03, B04, B05') on conflict (id) do nothing;
insert into public.actor_cards (id, actor_name, scene_title, thread, status, session_date, actor_brief, actor_direction, questions, optional_action, director_goal, director_notes, shot_ids) values ('AC-002', 'Bryan', 'One director, many opinions', 'Bryan vs Everybody', 'Idea', NULL, 'The audience is following the complexity of coordinating a large theater production.', 'Talk about what you are trying to accomplish today; answer in your own words.', 'What is the main thing you need everyone to understand today?
Which scene is the trickiest to coordinate?
How do you know when a rehearsal went well?', 'Optional brief interview after rehearsal; do not interrupt work.', 'Capture an authentic organizing perspective to contrast with actual rehearsals.', 'Keep conflicts playful and fair; do not fabricate an actor dispute.', 'R02, R03, R04') on conflict (id) do nothing;
insert into public.actor_cards (id, actor_name, scene_title, thread, status, session_date, actor_brief, actor_direction, questions, optional_action, director_goal, director_notes, shot_ids) values ('AC-003', 'Johanna', 'Understudy conspiracy', 'Understudy Conspiracy', 'Idea', NULL, 'The documentary explores how much preparation understudying requires, with the crew treating your readiness with unnecessary suspicion.', 'Explain your real preparation. No suggestion of actual sabotage or wrongdoing.', 'How much material have you needed to learn?
How prepared do you have to be?
What do people misunderstand about understudying?', 'If there is time after rehearsal, record a brief interview with your script nearby.', 'Film real dedication that the edit may frame as a lighthearted mock mystery.', 'Johanna was understudy, not Courtney. Keep the character distinction.', 'S06, S07') on conflict (id) do nothing;
insert into public.actor_cards (id, actor_name, scene_title, thread, status, session_date, actor_brief, actor_direction, questions, optional_action, director_goal, director_notes, shot_ids) values ('AC-004', 'Adult choir member / leader', 'Four Boxes, One Choir', 'Four Boxes One Choir', 'Idea', NULL, 'The documentary is attempting to understand how the choir gets organized into four positions.', 'Explain how the boxes really work and what makes transitions challenging.', 'Can you explain the four boxes?
How does everybody know where to go?
What changes when the group rehearses onstage?', 'Point out the boxes or marks when rehearsal is not active.', 'Establish the running organizational joke without filming children without permission.', 'Verify the actual setup with choir leadership first.', 'S04, S05, E10') on conflict (id) do nothing;
